<?php
namespace App\Http\Controllers\Admin;
use App\Http\Controllers\Controller; use App\Http\Requests\AdminLoginRequest; use Illuminate\Http\JsonResponse; use Illuminate\Http\Request; use Illuminate\Support\Facades\Auth; use Illuminate\Support\Facades\RateLimiter; use Illuminate\Validation\ValidationException;
class AuthController extends Controller { public function login(AdminLoginRequest $request): JsonResponse { $key=strtolower($request->input('email')).'|'.$request->ip(); if(RateLimiter::tooManyAttempts($key,5)) throw ValidationException::withMessages(['email'=>'Quá nhiều lần đăng nhập thất bại.']); if(!Auth::guard('admin')->attempt($request->only('email','password'),$request->boolean('remember'))){RateLimiter::hit($key,60); throw ValidationException::withMessages(['email'=>'Thông tin đăng nhập không hợp lệ.']);} RateLimiter::clear($key); $request->session()->regenerate(); return response()->json(['data'=>Auth::guard('admin')->user()]); } public function logout(Request $request): JsonResponse { Auth::guard('admin')->logout(); $request->session()->invalidate(); $request->session()->regenerateToken(); return response()->json(['message'=>'logged_out']); } }
